-- Übungskatalog aus free-exercise-db (gemeinfrei). Erzeugt von tools/build-seed.mjs.
-- 78 Übungen, Teil 4 von 4. Deutsche Namen sind maschinell erzeugt und dürfen angepasst werden.
--
-- Das Skript ist wiederholbar: bereits vorhandene Katalogübungen (source + source_id)
-- werden aktualisiert (Namen, Muskelgruppen, Gerät, englische Anleitung). Ihre IDs bleiben
-- gleich, Pläne und Trainings bleiben also verknüpft. Deine eigenen Übungen und deine
-- deutschen Anleitungen (instructions_de) bleiben unberührt.
-- Die Übungen gehören dem ersten (einzigen) Nutzer in auth.users. Lege dein Konto
-- deshalb an, bevor du dieses Skript ausführst.

do $seed$
declare uid uuid;
begin
  select id into uid from auth.users order by created_at limit 1;
  if uid is null then
    raise exception 'Kein Nutzer in auth.users. Lege zuerst dein Konto an (Authentication > Users).';
  end if;

  insert into fit_exercises
    (user_id, source, source_id, name_en, name_de, primary_muscles, secondary_muscles, equipment, instructions_en)
  select uid, 'free-exercise-db', v.source_id, v.name_en, v.name_de, v.primary_muscles, v.secondary_muscles, v.equipment, v.instructions_en
  from (values
    ('Standing_Low-Pulley_Deltoid_Raise', 'Standing Low-Pulley Deltoid Raise', 'Stehendes Schulterheben am unteren Kabelzug', array['shoulders']::text[], array['forearms']::text[], 'cable', array['Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance.', 'Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting position.', 'Begin to use the left hand and come across your body out until it is elevated to shoulder height while exhaling.', 'Feel the contraction at the top for a second and begin to slowly lower the handle back down to the original starting position while inhaling.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.']::text[]),
    ('Standing_Low-Pulley_One-Arm_Triceps_Extension', 'Standing Low-Pulley One-Arm Triceps Extension', 'Stehende einarmige Trizeps-Extension am unteren Kabelzug', array['triceps']::text[], array['chest', 'shoulders']::text[], 'cable', array['Grab a single handle with your left arm next to the low pulley machine. Turn away from the machine keeping the handle to the side of your body with your arm fully extended. Now use both hands to elevate the single handle directly above the head with the palm facing forward. Keep your upper arm completely vertical (perpendicular to the floor) and put your right hand on your left elbow to help keep it steady. This is the starting position.', 'Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the single handle. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.']::text[]),
    ('Standing_Military_Press', 'Standing Military Press', 'Stehendes Schulterdrücken (Military Press)', array['shoulders']::text[], array['triceps']::text[], 'barbell', array['Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.', 'Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.', 'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the collarbone slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Standing_Olympic_Plate_Hand_Squeeze', 'Standing Olympic Plate Hand Squeeze', 'Scheibendrücken im Stehen (olympische Scheibe)', array['forearms']::text[], array['biceps']::text[], 'other', array['To begin, stand straight while holding a weight plate by the ridge at arm''s length in each hand using a neutral grip (palms facing in). You feet should be shoulder width apart from each other. This will be your starting position.', 'Lower the plates until the fingers are nearly extended but can still hold weights. Inhale as you lower the plates.', 'Now raise the plates back to the starting position as you exhale by closing your hands.', 'Repeat for the recommended amount of repetitions prescribed in your program.']::text[]),
    ('Standing_One-Arm_Cable_Curl', 'Standing One-Arm Cable Curl', 'Stehender einarmiger Curl am Kabelzug', array['biceps']::text[], '{}'::text[], 'cable', array['Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight.', 'Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance.', 'Slowly begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your bicep while exhaling. Tip: Only the forearm should move.', 'Hold the contraction position as you squeeze the bicep and then lower the single handle back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.', 'Switch arms while performing this exercise.']::text[]),
    ('Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench', 'Standing One-Arm Dumbbell Curl Over Incline Bench', 'Stehender einarmiger Kurzhantel-Curl über der Schrägbank', array['biceps']::text[], '{}'::text[], 'dumbbell', array['Stand on the back side of an incline bench as if you were going to be a spotter for someone. Have a dumbbell in one hand and rest it across the incline bench with a supinated (palms up) grip.', 'Position your non lifting hand at the corner or side of the incline bench. The chest should be pressed against the top part of the incline and your feet should be pressed against the floor at a wide stance. This is the starting position.', 'While holding the upper arm stationary, curl the dumbbell upward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a second.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.', 'Switch arms while performing this exercise.']::text[]),
    ('Standing_One-Arm_Dumbbell_Triceps_Extension', 'Standing One-Arm Dumbbell Triceps Extension', 'Stehende einarmige Kurzhantel-Trizeps-Extension', array['triceps']::text[], array['chest', 'shoulders']::text[], 'dumbbell', array['To begin, stand up with a dumbbell held in one hand. Your feet should be about shoulder width apart from each other. Now fully extend the arm with the dumbbell over your head. Tip: The small finger of your hand should be facing the ceiling and the palm of your hand should be facing forward. The dumbbell should be above your head.', 'This will be your starting position.', 'Keeping your upper arm close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearm touch your bicep. Tip: The upper arm should remain stationary and only the forearm should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.']::text[]),
    ('Standing_Overhead_Barbell_Triceps_Extension', 'Standing Overhead Barbell Triceps Extension', 'Stehende Langhantel-Trizeps-Extension über Kopf', array['triceps']::text[], array['shoulders']::text[], 'barbell', array['To begin, stand up holding a barbell or e-z bar using a pronated grip (palms facing forward) with your hands closer than shoulder width apart from each other. Your feet should be about shoulder width apart.', 'Now elevate the barbell above your head until your arms are fully extended. Keep your elbows in. This will be your starting position.', 'Keeping your upper arms close to your head and elbows in, perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the barbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Standing_Palm-In_One-Arm_Dumbbell_Press', 'Standing Palm-In One-Arm Dumbbell Press', 'Stehendes einarmiges Kurzhantel-Drücken, neutraler Griff', array['shoulders']::text[], array['triceps']::text[], 'dumbbell', array['Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline bench to keep your balance.', 'Your feet should be shoulder width apart from each other. Now slowly lift the dumbbell up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to the floor. Continue to maintain a neutral grip throughout the entire exercise.', 'Slowly lift the dumbbell up until your arm is fully extended. This the starting position.', 'While inhaling lower the weight down until your arm is at a 90 degree angle again.', 'Feel the contraction for a second and then lift the weight back up towards the starting position while exhaling. Remember to hold on to the incline bench and keep your feet positioned to keep balance during the exercise.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.']::text[]),
    ('Standing_Palms-In_Dumbbell_Press', 'Standing Palms-In Dumbbell Press', 'Stehendes Kurzhantel-Drücken, neutraler Griff', array['shoulders']::text[], array['triceps']::text[], 'dumbbell', array['Start by having a dumbbell in each hand with your arm fully extended to the side using a neutral grip. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbells up until you create a 90 degree angle with your arms. Note: Your forearms should be perpendicular to the floor. This the starting position.', 'Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the dumbbells up until your arms are fully extended.', 'While inhaling lower the weights down until your arm is at a 90 degree angle again.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl', 'Standing Palms-Up Barbell Behind The Back Wrist Curl', 'Stehender Langhantel-Handgelenk-Curl hinter dem Rücken, Untergriff', array['forearms']::text[], '{}'::text[], 'barbell', array['Start by standing straight and holding a barbell behind your glutes at arm''s length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other.', 'You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position.', 'While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only body part moving for this exercise.', 'Hold the contraction for a second and lower the barbell back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.', 'When finished, lower the barbell down to the squat rack or the floor by bending the knees. Tip: It is easiest to either pick it up from a squat rack or have a partner hand it to you.']::text[]),
    ('Standing_Rope_Crunch', 'Standing Rope Crunch', 'Stehender Seil-Crunch', array['abdominals']::text[], '{}'::text[], 'cable', array['Attach a rope to a high pulley and select an appropriate weight.', 'Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position.', 'Perform the movement by flexing the spine, crunching the weight down as far as you can.', 'Hold the peak contraction for a moment before returning to the starting position.']::text[]),
    ('Standing_Towel_Triceps_Extension', 'Standing Towel Triceps Extension', 'Stehende Trizeps-Extension mit Handtuch', array['triceps']::text[], '{}'::text[], 'body only', array['To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position.', 'Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the towel. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Step-up_with_Knee_Raise', 'Step-up with Knee Raise', 'Step-up mit Knieheben', array['glutes']::text[], array['hamstrings', 'quadriceps']::text[], 'body only', array['Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.', 'Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.', 'Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg.']::text[]),
    ('Stiff-Legged_Barbell_Deadlift', 'Stiff-Legged Barbell Deadlift', 'Langhantel-Kreuzheben mit gestreckten Beinen', array['hamstrings']::text[], array['glutes', 'lower back']::text[], 'barbell', array['Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.', 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.', 'Start bringing your torso up straight again by extending your hips until you are back at the starting position. Exhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Stiff-Legged_Dumbbell_Deadlift', 'Stiff-Legged Dumbbell Deadlift', 'Kurzhantel-Kreuzheben mit gestreckten Beinen', array['hamstrings']::text[], array['glutes', 'lower back']::text[], 'dumbbell', array['Grasp a couple of dumbbells holding them by your side at arm''s length.', 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement', 'Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Stiff_Leg_Barbell_Good_Morning', 'Stiff Leg Barbell Good Morning', 'Good Morning mit gestreckten Beinen (Langhantel)', array['lower back']::text[], array['glutes', 'hamstrings']::text[], 'barbell', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position.', 'Keeping your legs stationary, move your torso forward by bending at the hips while inhaling. Lower your torso until it is parallel with the floor.', 'Begin to raise the bar as you exhale by elevating your torso back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Straight-Arm_Dumbbell_Pullover', 'Straight-Arm Dumbbell Pullover', 'Kurzhantel-Überzug mit gestreckten Armen', array['chest']::text[], array['lats', 'shoulders', 'triceps']::text[], 'dumbbell', array['Place a dumbbell standing up on a flat bench.', 'Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.', 'Grasp the dumbbell with both hands and hold it straight over your chest at arms length. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position.
Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.', 'While keeping your arms straight, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.', 'At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.', 'Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.']::text[]),
    ('Straight-Arm_Pulldown', 'Straight-Arm Pulldown', 'Latziehen mit gestreckten Armen', array['lats']::text[], '{}'::text[], 'cable', array['You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.', 'Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.', 'While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.', 'While keeping the arms straight, go back to the starting position while breathing in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Straight_Bar_Bench_Mid_Rows', 'Straight Bar Bench Mid Rows', 'Rudern bäuchlings auf der Bank mit gerader Stange', array['middle back']::text[], array['biceps', 'lats']::text[], 'barbell', array['Place a loaded barbell on the end of a bench. Standing on the bench behind the bar, take a medium, pronated grip. Stand with your hips back and chest up, maintaining a neutral spine. This will be your starting position.', 'Row the bar to your torso by retracting the shoulder blades and flexing the elbows. Use a controlled movement with no jerking.', 'After a brief pause, slowly return the bar to the starting position, ensuring to go all the way down.']::text[]),
    ('Straight_Raises_on_Incline_Bench', 'Straight Raises on Incline Bench', 'Frontheben bäuchlings an der Schrägbank', array['shoulders']::text[], array['traps']::text[], 'barbell', array['Place a bar on the ground behind the head of an incline bench.', 'Lay on the bench face down. With a pronated grip, pick the barbell up from the floor, keeping your arms straight. Allow the bar to hang straight down. This will be your starting position.', 'To begin, raise the barbell out in front of your head while keeping your arms extended.', 'Return to the starting position.']::text[]),
    ('Sumo_Deadlift', 'Sumo Deadlift', 'Sumo-Kreuzheben', array['hamstrings']::text[], array['adductors', 'forearms', 'glutes', 'lower back', 'middle back', 'quadriceps', 'traps']::text[], 'barbell', array['Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[]),
    ('Sumo_Deadlift_with_Bands', 'Sumo Deadlift with Bands', 'Sumo-Kreuzheben mit Bändern', array['hamstrings']::text[], array['adductors', 'forearms', 'glutes', 'lower back', 'middle back', 'quadriceps', 'traps']::text[], 'barbell', array['To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. Ensure that they under the back half of your foot, directly where you are driving into the floor.', 'Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[]),
    ('Sumo_Deadlift_with_Chains', 'Sumo Deadlift with Chains', 'Sumo-Kreuzheben mit Ketten', array['hamstrings']::text[], array['abductors', 'adductors', 'forearms', 'glutes', 'lower back', 'middle back', 'quadriceps', 'traps']::text[], 'barbell', array['You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Attempt to keep the ends of the chains away from the plates so you don''t hit them when you lower the weight.', 'Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[]),
    ('Suspended_Fallout', 'Suspended Fallout', 'Suspended Fallout', array['abdominals']::text[], array['chest', 'lower back', 'shoulders']::text[], 'other', array['Adjust the straps so the handles are at an appropriate height, below waist level.', 'Begin standing and grasping the handles. Lean into the straps, moving to an incline push-up position. This will be your starting position.', 'Keeping your arms straight, lean further into the suspension straps, bringing your body closer to the ground, allowing your shoulders to extend, raising your arms up and over your head.', 'Maintain a neutral spine and keep the rest of your body straight, your shoulders being the only joints allowed to move.', 'Pause during the peak contraction, and then return to the starting position.']::text[]),
    ('Suspended_Push-Up', 'Suspended Push-Up', 'Liegestütz an Schlingen', array['chest']::text[], array['shoulders', 'triceps']::text[], 'other', array['Anchor your suspension straps securely to the top of a rack or other object.', 'Leaning into the straps, take a handle in each hand and move into a push-up plank position. You should be as close to parallel to the ground as you can manage with your arms fully extended, maintaining good posture.', 'Maintaining a straight, rigid torso, descend slowly by allowing the elbows to flex.', 'Continue until your elbows break 90 degrees, pausing before you extend to return to the starting position.']::text[]),
    ('Suspended_Reverse_Crunch', 'Suspended Reverse Crunch', 'Reverse Crunch an Schlingen', array['abdominals']::text[], '{}'::text[], 'other', array['Secure a set of suspension straps with the handles hanging about a foot off of the ground. Move yourself into a pushup plank position facing away from the rack.', 'Place your feet into the handles. You should maintain a straight posture, not allowing the hips to sag. This will be your starting position.', 'Begin the movement by flexing the knees and hips, drawing the knees to your torso. As you do so, anteriorly tilt your pelvis, allowing your spine to flex.', 'At the top of the controlled motion, return to the starting position.']::text[]),
    ('Suspended_Row', 'Suspended Row', 'Rudern an Schlingen', array['middle back']::text[], array['biceps', 'lats']::text[], 'other', array['Suspend your straps at around chest height. Take a handle in each hand and lean back. Keep your body erect and your head and chest up. Your arms should be fully extended. This will be your starting position.', 'Begin by flexing the elbow to initiate the movement. Protract your shoulder blades as you do so.', 'At the completion of the motion pause, and then return to the starting position.']::text[]),
    ('Suspended_Split_Squat', 'Suspended Split Squat', 'Split Squat an Schlingen', array['quadriceps']::text[], array['abductors', 'adductors', 'calves', 'glutes', 'hamstrings']::text[], 'other', array['Suspend your straps so the handles are 18-30 inches from the floor.', 'Facing away from the setup, place your rear foot into the handle behind you. Keep your head looking forward and your chest up, with your knee slightly bent. This will be your starting position.', 'Descend by flexing the knee and hips, lowering yourself to the ground. Keep your weight on the heel of your foot and maintain your posture throughout the exercise.', 'At the bottom of the movement, reverse the motion, extending through the hip and knee to return to the starting position.']::text[]),
    ('Svend_Press', 'Svend Press', 'Svend Press', array['chest']::text[], array['forearms', 'shoulders', 'triceps']::text[], 'other', array['Begin in a standing position.', 'Press two lightweight plates together with your hands. Hold the plates together close to your chest to create an isometric contraction in your chest muscles. Your fingers should be pointed forward. This is your starting position.', 'Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion.', 'Pause at the top of the motion, and then slowly return to the starting position.']::text[]),
    ('T-Bar_Row_with_Handle', 'T-Bar Row with Handle', 'T-Bar-Rudern mit Griff', array['middle back']::text[], array['biceps', 'lats']::text[], 'barbell', array['Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.', 'Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position.', 'Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position.', 'Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weight or cheat during the movement.', 'After a brief pause, return to the starting position.']::text[]),
    ('Tate_Press', 'Tate Press', 'Tate Press', array['triceps']::text[], array['chest', 'shoulders']::text[], 'dumbbell', array['Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other.', 'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a pronated (palms forward) grip. Allow your elbows to point out. This is your starting position.', 'Keeping the upper arms stationary, slowly move the dumbbells in and down in a semi circular motion until they touch the upper chest while inhaling. Keep full control of the dumbbells at all times and do not move the upper arms nor rest the dumbbells on the chest.', 'As you breathe out, move the dumbbells up using your triceps and the same semi-circular motion but in reverse. Attempt to keep the dumbbells together as they move up. Lock your arms in the contracted position, hold for a second and then start coming down again slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[]),
    ('Thigh_Abductor', 'Thigh Abductor', 'Abduktorenmaschine', array['abductors']::text[], array['glutes']::text[], 'machine', array['To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them away from each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Thigh_Adductor', 'Thigh Adductor', 'Adduktorenmaschine', array['adductors']::text[], array['glutes', 'hamstrings']::text[], 'machine', array['To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them towards each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Tire_Flip', 'Tire Flip', 'Reifen wenden', array['quadriceps']::text[], array['calves', 'chest', 'forearms', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps', 'triceps']::text[], 'other', array['Begin by gripping the bottom of the tire on the tread, and position your feet back a bit. Your chest should be driving into the tire.', 'To lift the tire, extend through the hips, knees, and ankles, driving into the tire and up.', 'As the tire reaches a 45 degree angle, step forward and drive a knee into the tire. As you do so adjust your grip to the upper portion of the tire and push it forward as hard as possible to complete the turn. Repeat as necessary.']::text[]),
    ('Trap_Bar_Deadlift', 'Trap Bar Deadlift', 'Trap-Bar-Kreuzheben', array['quadriceps']::text[], array['glutes', 'hamstrings']::text[], 'other', array['For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.', 'Lower your hips, look forward with your head and keep your chest up.', 'Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.', 'At the completion of the movement, lower the weight back to the ground under control.']::text[]),
    ('Tricep_Dumbbell_Kickback', 'Tricep Dumbbell Kickback', 'Kurzhantel-Kickback', array['triceps']::text[], '{}'::text[], 'dumbbell', array['Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.', 'Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.', 'After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat the movement for the prescribed amount of repetitions.']::text[]),
    ('Triceps_Overhead_Extension_with_Rope', 'Triceps Overhead Extension with Rope', 'Trizeps-Extension über Kopf mit Seil', array['triceps']::text[], '{}'::text[], 'cable', array['Attach a rope to a low pulley. After selecting an appropriate weight, grasp the rope with both hands and face away from the cable.', 'Position your hands behind your head with your elbows point straight up. Your elbows should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. This will be your starting position.', 'To perform the movement, extend through the elbow while keeping the upper arm in position, raising your hands above your head.', 'Squeeze your triceps at the top of the movement, and slowly lower the weight back to the start position.']::text[]),
    ('Triceps_Pushdown', 'Triceps Pushdown', 'Trizepsdrücken am Kabelzug', array['triceps']::text[], '{}'::text[], 'cable', array['Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.', 'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Triceps_Pushdown_-_Rope_Attachment', 'Triceps Pushdown - Rope Attachment', 'Trizepsdrücken am Kabelzug (Seil)', array['triceps']::text[], '{}'::text[], 'cable', array['Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.', 'Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Triceps_Pushdown_-_V-Bar_Attachment', 'Triceps Pushdown - V-Bar Attachment', 'Trizepsdrücken am Kabelzug (V-Stange)', array['triceps']::text[], '{}'::text[], 'cable', array['Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position.', 'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After a second hold at the contracted position, bring the V-Bar slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Tuck_Crunch', 'Tuck Crunch', 'Tuck Crunch', array['abdominals']::text[], '{}'::text[], 'body only', array['To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.', 'Your legs should be crossed by wrapping one ankle around the other. Slowly elevate your legs up in the air until your thighs are perpendicular to the floor with a slight bend at the knees. Note: Your knees and toes should be parallel to the floor as opposed to the thighs.', 'Move your arms from the floor and cross them so they are resting on your chest. This is the starting position.', 'While keeping your lower back pressed against the floor, slowly lift your torso. Remember to exhale while perform this part of the exercise.', 'Slowly begin to lower your torso back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Two-Arm_Dumbbell_Preacher_Curl', 'Two-Arm Dumbbell Preacher Curl', 'Beidarmiger Kurzhantel-Scott-Curl', array['biceps']::text[], '{}'::text[], 'dumbbell', array['Grab a dumbbell with each arm and place the upper arms on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.', 'As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weights up until your biceps is fully contracted and the dumbbells are at shoulder height.', 'Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.']::text[]),
    ('Two-Arm_Kettlebell_Clean', 'Two-Arm Kettlebell Clean', 'Beidarmiges Kettlebell-Umsetzen', array['shoulders']::text[], array['calves', 'glutes', 'hamstrings', 'lower back', 'traps']::text[], 'kettlebells', array['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean the kettlebells to your shoulders by extending through the legs and hips as you raise the kettlebells towards your shoulders. Rotate your wrists as you do so.', 'Lower the kettlebells back to the starting position and repeat.']::text[]),
    ('Two-Arm_Kettlebell_Jerk', 'Two-Arm Kettlebell Jerk', 'Beidarmiges Kettlebell-Stoßen', array['shoulders']::text[], array['calves', 'quadriceps', 'triceps']::text[], 'kettlebells', array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once the kettlebells are locked out, stand upright to complete the exercise.']::text[]),
    ('Two-Arm_Kettlebell_Military_Press', 'Two-Arm Kettlebell Military Press', 'Beidarmiges Kettlebell-Schulterdrücken', array['shoulders']::text[], array['triceps']::text[], 'kettlebells', array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward.', 'Press the kettlebells up and out. As the kettlebells pass your head, lean into the weights so that the kettlebells are racked behind your head. Make sure to contract your lats, butt, and stomach for added stability.']::text[]),
    ('Two-Arm_Kettlebell_Row', 'Two-Arm Kettlebell Row', 'Beidarmiges Kettlebell-Rudern', array['middle back']::text[], array['biceps', 'lats']::text[], 'kettlebells', array['Place two kettlebells in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position.', 'Grab both kettlebells and pull them to your stomach, retracting your shoulder blades and flexing the elbows. Keep your back straight. Lower and repeat.']::text[]),
    ('Underhand_Cable_Pulldowns', 'Underhand Cable Pulldowns', 'Latziehen im Untergriff am Kabelzug', array['lats']::text[], array['biceps', 'middle back', 'shoulders']::text[], 'cable', array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, pull the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the fully contracted position and keep the elbows close to your body. The upper torso should remain stationary as your bring the bar to you and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, while breathing in, slowly bring the bar back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.']::text[]),
    ('Upright_Barbell_Row', 'Upright Barbell Row', 'Langhantel-Aufrechtrudern', array['shoulders']::text[], array['traps']::text[], 'barbell', array['Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.', 'Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should drive the motion, and should always be higher than your forearms. Remember to keep your torso stationary and pause for a second at the top of the movement.', 'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Upright_Cable_Row', 'Upright Cable Row', 'Aufrechtrudern am Kabelzug', array['traps']::text[], array['shoulders']::text[], 'cable', array['Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The bar should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the cable bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Upright_Row_-_With_Bands', 'Upright Row - With Bands', 'Aufrechtrudern mit Bändern', array['traps']::text[], array['shoulders']::text[], 'bands', array['To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('V-Bar_Pulldown', 'V-Bar Pulldown', 'Latziehen mit V-Griff', array['lats']::text[], array['biceps', 'middle back', 'shoulders']::text[], 'cable', array['Sit down on a pull-down machine with a V-Bar attached to the top pulley.', 'Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.', 'Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion. Tip: Keep the torso stationary throughout the movement.', 'After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.', 'Repeat for the prescribed number of repetitions.']::text[]),
    ('V-Bar_Pullup', 'V-Bar Pullup', 'Klimmzug am V-Griff', array['lats']::text[], array['biceps', 'middle back', 'shoulders']::text[], 'body only', array['Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles.', 'Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly in order to better engage the lats. This will be your starting position.', 'Using your lats, pull your torso up while leaning your head back slightly so that you do not hit yourself with the chin-up bar. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion.', 'After a second hold on the contracted position, slowly lower your body back to the starting position as you breathe in.', 'Repeat for the prescribed number of repetitions.']::text[]),
    ('Weighted_Ball_Hyperextension', 'Weighted Ball Hyperextension', 'Rückenstrecker mit Gewichtsball', array['lower back']::text[], array['glutes', 'hamstrings', 'middle back']::text[], 'exercise ball', array['To begin, lie down on an exercise ball with your torso pressing against the ball and parallel to the floor. The ball of your feet should be pressed against the floor to help keep you balanced. Place a weighted plate under your chin or behind your neck. This is the starting position.', 'Slowly raise your torso up by bending at the waist and lower back. Remember to exhale during this movement.', 'Hold the contraction on your lower back for a second and lower your torso back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions prescribed in your program.']::text[]),
    ('Weighted_Ball_Side_Bend', 'Weighted Ball Side Bend', 'Seitbeugen mit Gewichtsball', array['abdominals']::text[], '{}'::text[], 'exercise ball', array['To begin, lie down on an exercise ball with your left side of the torso (waist, hips and shoulder) pressed against the ball.', 'Your feet should be on the floor while your legs are crossed and hanging from the ball. Hold a weighted plate with your right hand directly to the right side of your head. Tip: Make sure the smooth side of the plate is resting against your head.', 'Place your left arm across your torso so that your palm is on your obliques. There should be a right angle between your left forearm and upper arm. This is the starting position.', 'Raise the side of your torso up by laterally flexing at the waist while exhaling.', 'Hold the contraction for a second and slowly lower yourself back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.', 'Switch sides and repeat the exercise.']::text[]),
    ('Weighted_Bench_Dip', 'Weighted Bench Dip', 'Bankdips mit Zusatzgewicht', array['triceps']::text[], array['chest', 'shoulders']::text[], 'other', array['For this exercise you will need to place a bench behind your back and another one in front of you. With the benches perpendicular to your body, hold on to one bench on its edge with the hands close to your body, separated at shoulder width. Your arms should be fully extended.', 'The legs will be extended forward on top of the other bench. Your legs should be parallel to the floor while your torso is to be perpendicular to the floor. Have your partner place the dumbbell on your lap. Note: This exercise is best performed with a partner as placing the weight on your lap can be challenging and cause injury without assistance. This will be your starting position.', 'Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.', 'Using your triceps to bring your torso up again, lift yourself back to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Weighted_Crunches', 'Weighted Crunches', 'Crunches mit Zusatzgewicht', array['abdominals']::text[], '{}'::text[], 'medicine ball', array['Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle.', 'Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position.', 'Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor.', 'At the top of the movement, flex your abdominals and hold for a brief pause.', 'Then inhale and slowly lower yourself back down to the starting position.']::text[]),
    ('Weighted_Jump_Squat', 'Weighted Jump Squat', 'Sprung-Kniebeuge mit Zusatzgewicht', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings', 'lower back']::text[], 'barbell', array['Position a lightly loaded barbell across the back of your shoulders. You could also use a weighted vest, sandbag, or other type of resistance for this exercise.', 'The weight should be light enough that it doesn''t slow you down significantly. Your feet should be just outside of shoulder width with your head and chest up. This will be your starting position.', 'Using a countermovement, squat partially down and immediately reverse your direction to explode off of the ground, extending through your hips, knees, and ankles. Maintain good posture throughout the jump.', 'As you return to the ground, absorb the impact through your legs.']::text[]),
    ('Weighted_Pull_Ups', 'Weighted Pull Ups', 'Klimmzüge mit Zusatzgewicht', array['lats']::text[], array['biceps', 'middle back']::text[], 'other', array['Attach a weight to a dip belt and secure it around your waist. Grab the pull-up bar with the palms of your hands facing forward. For a medium grip, your hands should be spaced at shoulder width. Both arms should be extended in front of you holding the bar at the chosen grip.', 'You''ll want to bring your torso back about 30 degrees while creating a curvature in your lower back and sticking your chest out. This will be your starting position.', 'Now, exhale and pull your torso up until your head is above your hands. Concentrate on squeezing yourshoulder blades back and down as you reach the top contracted position.', 'After a brief moment at the top contracted position, inhale and slowly lower your torso back to the starting position with your arms extended and your lats fully stretched.']::text[]),
    ('Weighted_Sissy_Squat', 'Weighted Sissy Squat', 'Sissy Squat mit Zusatzgewicht', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'barbell', array['Standing upright, with feet at shoulder width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your chest. This is your starting position.', 'As you use one arm to hold yourself, bend at the knees and slowly lower your torso toward the ground by bringing your pelvis and knees forward. Inhale as you go down and stop when your upper and lower legs almost create a 90-degree angle. Hold the stretch position for a second.', 'After your one second hold, use your thigh muscles to bring your torso back up to the starting position. Exhale as you move up.', 'Repeat for the recommended amount of times.']::text[]),
    ('Weighted_Sit-Ups_-_With_Bands', 'Weighted Sit-Ups - With Bands', 'Sit-ups mit Zusatzgewicht und Bändern', array['abdominals']::text[], '{}'::text[], 'other', array['Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them.', 'Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain stationary throughout the exercise. This is the starting position.', 'Move your torso upward until your upper body is perpendicular to the floor while exhaling. Hold the contraction for a second and lower your upper body back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Weighted_Squat', 'Weighted Squat', 'Kniebeuge mit Zusatzgewicht', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'other', array['Start by positioning two flat benches shoulder width apart from each other. Stand on top of them and wrap the weighted belt around your waist with the amount of weight you feel comfortable with. Make sure your toes are facing out.', 'Once you are standing straight up with the weight hanging in between your legs, position your arms so that they are fully extended to the side of your body. This is the starting position.', 'Begin by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that are perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to move the body back up by pushing the floor of the flat bench with the ball of your foot mainly as you straighten the legs again and go back to the starting position. Exhale as you perform this portion of the exercise.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Wide-Grip_Barbell_Bench_Press', 'Wide-Grip Barbell Bench Press', 'Langhantel-Bankdrücken, weiter Griff', array['chest']::text[], array['shoulders', 'triceps']::text[], 'barbell', array['Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.']::text[]),
    ('Wide-Grip_Decline_Barbell_Bench_Press', 'Wide-Grip Decline Barbell Bench Press', 'Langhantel-Negativbankdrücken, weiter Griff', array['chest']::text[], array['shoulders', 'triceps']::text[], 'barbell', array['Lie back on a decline bench with the feet securely locked at the front of the bench. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your lower chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.']::text[]),
    ('Wide-Grip_Decline_Barbell_Pullover', 'Wide-Grip Decline Barbell Pullover', 'Langhantel-Überzug an der Negativbank, weiter Griff', array['chest']::text[], array['shoulders', 'triceps']::text[], 'barbell', array['Lie down on a decline bench with both legs securely locked in position. Reach for the barbell behind the head using a pronated grip (palms facing out). Make sure to grab the barbell wider than shoulder width apart for this exercise. Slowly lift the barbell up from the floor by using your arms.', 'When positioned properly, your arms should be fully extended and perpendicular to the floor. This is the starting position.', 'Begin by moving the barbell back down in a semicircular motion as if you were going to place it on the floor, but instead, stop when the arms are parallel to the floor. Tip: Keep the arms fully extended at all times. The movement should only happen at the shoulder joint. Inhale as you perform this portion of the movement.', 'Now bring the barbell up while exhaling until you are back at the starting position. Remember to keep full control of the barbell at all times.', 'Repeat the movement for the prescribed amount of repetitions of your training program.', 'When finished with your set, slowly lower the barbell back down until it is level with your head and release it.']::text[]),
    ('Wide-Grip_Lat_Pulldown', 'Wide-Grip Lat Pulldown', 'Latziehen, weiter Griff', array['lats']::text[], array['biceps', 'middle back', 'shoulders']::text[], 'cable', array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.', 'After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.']::text[]),
    ('Wide-Grip_Pulldown_Behind_The_Neck', 'Wide-Grip Pulldown Behind The Neck', 'Latziehen hinter den Nacken, weiter Griff', array['lats']::text[], array['biceps', 'middle back', 'shoulders']::text[], 'cable', array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso and head forward. Think of an imaginary line from the center of the bar down to the back of your neck. This is your starting position.', 'As you breathe out, bring the bar down until it touches the back of your neck by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.', 'After a second on the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.']::text[]),
    ('Wide-Grip_Rear_Pull-Up', 'Wide-Grip Rear Pull-Up', 'Nackenklimmzug, weiter Griff', array['lats']::text[], array['biceps', 'middle back', 'shoulders']::text[], 'body only', array['Grab the pull-up bar with the palms facing forward using a wide grip.', 'As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position.', 'Pull your torso up until the bar is near the back of your neck. To do this, draw the shoulders and upper arms down and back while slightly leaning your head forward. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.']::text[]),
    ('Wide-Grip_Standing_Barbell_Curl', 'Wide-Grip Standing Barbell Curl', 'Stehender Langhantel-Curl, weiter Griff', array['biceps']::text[], '{}'::text[], 'barbell', array['Stand up with your torso upright while holding a barbell at the wide outer handle. The palm of your hands should be facing forward. The elbows should be close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Wide_Stance_Barbell_Squat', 'Wide Stance Barbell Squat', 'Langhantel-Kniebeuge, weiter Stand', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings', 'lower back']::text[], 'barbell', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a wider-than-shoulder-width stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance, and also maintain a straight back. This will be your starting position.', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Wide_Stance_Stiff_Legs', 'Wide Stance Stiff Legs', 'Kreuzheben mit gestreckten Beinen, weiter Stand', array['hamstrings']::text[], array['adductors', 'glutes', 'lower back']::text[], 'barbell', array['Begin with a barbell loaded on the floor. Adopt a wide stance, and then bend at the hips to grab the bar. Your hips should be as far back as possible, and your legs nearly straight. Keep your back straight, and your head and chest up. This will be your starting position.', 'Begin the movement be engaging the hips, driving them forward as you allow the arms to hang straight. Continue until you are standing straight up, and then slowly return the weight to the starting position. For successive reps, the weight need not touch the floor.']::text[]),
    ('Wind_Sprints', 'Wind Sprints', 'Sprints', array['abdominals']::text[], '{}'::text[], 'body only', array['Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position.', 'Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3', 'Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible.', 'Continue alternating between legs until the set is complete.']::text[]),
    ('Wrist_Roller', 'Wrist Roller', 'Unterarmroller (Wrist Roller)', array['forearms']::text[], array['shoulders']::text[], 'other', array['To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down). Your feet should be shoulder width apart.', 'Slowly lift both arms until they are fully extended and parallel to the floor in front of you. Note: Make sure the rope is not wrapped around the roller. Your entire body should be stationary except for the forearms. This is the starting position.', 'Rotate one wrist at a time in an upward motion to bring the weight up to the bar by rolling the rope around the roller.', 'Once the weight has reached the bar, slowly begin to lower the weight back down by rotating the wrist in a downward motion until the weight reaches the starting position.', 'Repeat for the prescribed amount of repetitions in your program.']::text[]),
    ('Wrist_Rotations_with_Straight_Bar', 'Wrist Rotations with Straight Bar', 'Handgelenkrotation mit gerader Stange', array['forearms']::text[], '{}'::text[], 'barbell', array['Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. This will be your starting position.', 'Alternating between each of your hands, perform the movement by extending the wrist as though you were rolling up a newspaper. Continue alternating back and forth until failure.', 'Reverse the motion by flexing the wrist, rolling the opposite direction. Continue the alternating motion until failure.']::text[]),
    ('Yoke_Walk', 'Yoke Walk', 'Yoke Walk', array['quadriceps']::text[], array['abdominals', 'abductors', 'adductors', 'calves', 'glutes', 'hamstrings', 'lower back']::text[], 'other', array['The yoke is usually done with a yoke apparatus, but is sometimes seen with refrigerators or other heavy objects.', 'Begin by racking the apparatus across the back of the shoulders. With your head looking forward and back arched, lift the yoke by driving through the heels.', 'Begin walking as quickly as possible using short, quick steps. You may hold the side posts of the yoke to help steady it and hold it in position. Continue for the given distance as fast as possible, usually 75-100 feet.']::text[]),
    ('Zercher_Squats', 'Zercher Squats', 'Zercher-Kniebeuge', array['quadriceps']::text[], array['calves', 'glutes', 'hamstrings']::text[], 'barbell', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the chest. Once the correct height is chosen and the bar is loaded, lock your hands together and place the bar on top of your arms in between the forearm and upper arm.', 'Lift the bar up so that it is resting on top of your forearms. If you are holding the bar properly, it should look as if you have your arms crossed but with a bar running across them.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the ball of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Zottman_Curl', 'Zottman Curl', 'Zottman-Curl', array['biceps']::text[], array['forearms']::text[], 'dumbbell', array['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.', 'Make sure the palms of the hands are facing each other. This will be your starting position.', 'While holding the upper arm stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Your wrist should rotate so that you have a supinated (palms up) grip. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a second as you squeeze the biceps.', 'Now during the contracted position, rotate your wrist until you now have a pronated (palms facing down) grip with the thumb at a higher position than the pinky.', 'Slowly begin to bring the dumbbells back down using the pronated grip.', 'As the dumbbells close your thighs, start rotating the wrist so that you go back to a neutral (palms facing your body) grip.', 'Repeat for the recommended amount of repetitions.']::text[]),
    ('Zottman_Preacher_Curl', 'Zottman Preacher Curl', 'Zottman-Scott-Curl', array['biceps']::text[], array['forearms']::text[], 'dumbbell', array['Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench. The dumbbells should be held at shoulder height and the elbows should be flexed. Hold the dumbbells with the palms of your hands facing down. This will be your starting position.', 'As you breathe in, slowly lower the dumbbells keeping the palms down until your upper arm is extended and your biceps are fully stretched.', 'Now rotate your wrists once you are at the bottom of the movement so that the palms of the hands are facing up.', 'As you exhale, use your biceps to curl the weights up until they are fully contracted and the dumbbells are at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.', 'Squeeze the biceps hard for a second at the contracted position and rotate your wrists so that the palms are facing down again.', 'Repeat for the recommended amount of repetitions.']::text[])
  ) as v(source_id, name_en, name_de, primary_muscles, secondary_muscles, equipment, instructions_en)
  on conflict (user_id, source, source_id) do update set
    name_en = excluded.name_en,
    name_de = excluded.name_de,
    primary_muscles = excluded.primary_muscles,
    secondary_muscles = excluded.secondary_muscles,
    equipment = excluded.equipment,
    instructions_en = excluded.instructions_en;
end
$seed$;
